import sqlite3, json
from collections import defaultdict

con = sqlite3.connect('analytics.db')
steps = ['install', 'tutorial_complete', 'first_match', 'purchase']

# filters: exclude test accounts and unknown players
users = {}
for uid, platform, is_test in con.execute('SELECT user_id, platform, is_test FROM users'):
    if not is_test:
        users[uid] = platform

events = defaultdict(lambda: defaultdict(list))  # uid -> step -> timestamps
names = set()
for uid, name, ts in con.execute('SELECT user_id, name, ts FROM events'):
    names.add(name)
    if uid in users and ts is not None:
        events[uid][name].append(ts)
print('event names seen:', names)

counts = defaultdict(lambda: [0]*len(steps))
for uid, platform in users.items():
    prev = None
    ev = events.get(uid, {})
    for i, s in enumerate(steps):
        times = sorted(ev.get(s, []))
        valid = [t for t in times if prev is None or t >= prev]
        if valid:
            counts[platform][i] += 1
            prev = valid[0]
        # no valid occurrence -> prev unchanged, later steps can't count (they must be >= prev of previous step; prev stays but subsequent steps require their own prev).
        else:
            break

result = {'funnel': {}, 'biggest_drop': {}}
for platform, c in sorted(counts.items()):
    result['funnel'][platform] = {s: n for s, n in zip(steps, c)}
    best = None
    for i in range(1, len(steps)):
        if c[i-1] == 0:
            continue
        conv = c[i]/c[i-1]
        if best is None or conv < best[1]:
            best = (steps[i], conv)
    result['biggest_drop'][platform] = best[0]

print(json.dumps(result, indent=2))
with open('result.json', 'w') as f:
    json.dump(result, f, indent=2)

# sanity: totals
print('total players per platform:', {p: sum(1 for u in users.values() if 0) for p in []} or
      {p: c[0] for p, c in counts.items()})


